//! Random, stable identifiers for mutable records.
//!
//! These are 128-bit values generated by the client that creates the record.
//! They never change: a change keeps its `ChangeId` across every amend and
//! rebase, which is what lets review state, provenance and CI results survive
//! history rewrites.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::error::{Error, Result};

macro_rules! define_id {
    ($(#[$meta:meta])* $name:ident, $prefix:literal) => {
        $(#[$meta])*
        #[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
        pub struct $name([u8; 16]);

        impl $name {
            pub const PREFIX: &'static str = $prefix;

            pub fn new() -> Self {
                $name(rand::random())
            }

            pub fn from_bytes(bytes: [u8; 16]) -> Self {
                $name(bytes)
            }

            pub fn as_bytes(&self) -> &[u8; 16] {
                &self.0
            }

            pub fn to_hex(&self) -> String {
                hex::encode(self.0)
            }

            /// Short prefix for display (10 hex chars).
            pub fn short(&self) -> String {
                self.to_hex()[..10].to_string()
            }

            /// Deterministic identifier derived from a name; used by importers
            /// and tests that need reproducible ids.
            pub fn derived(namespace: &str, name: &str) -> Self {
                let mut hasher = blake3::Hasher::new();
                hasher.update(b"rill:id:");
                hasher.update($prefix.as_bytes());
                hasher.update(b":");
                hasher.update(namespace.as_bytes());
                hasher.update(b":");
                hasher.update(name.as_bytes());
                let out = hasher.finalize();
                let mut bytes = [0u8; 16];
                bytes.copy_from_slice(&out.as_bytes()[..16]);
                $name(bytes)
            }
        }

        impl Default for $name {
            fn default() -> Self {
                Self::new()
            }
        }

        impl fmt::Debug for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}({})", stringify!($name), self.short())
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}_{}", $prefix, self.to_hex())
            }
        }

        impl FromStr for $name {
            type Err = Error;

            fn from_str(s: &str) -> Result<Self> {
                let hex_part = s
                    .strip_prefix(concat!($prefix, "_"))
                    .unwrap_or(s);
                let bytes = hex::decode(hex_part)
                    .map_err(|e| Error::InvalidId(format!("{s}: {e}")))?;
                let arr: [u8; 16] = bytes.try_into().map_err(|_| {
                    Error::InvalidId(format!("{s}: expected 16 bytes"))
                })?;
                Ok($name(arr))
            }
        }
    };
}

define_id!(
    /// Stable identity of a change across all of its versions.
    ChangeId,
    "ch"
);
define_id!(
    /// Identity of an intent (task, spec, bug, plan).
    IntentId,
    "in"
);
define_id!(
    /// Identity of a workspace: a principal's in-progress state on a repo.
    WorkspaceId,
    "ws"
);
define_id!(
    /// Identity of a principal (human, agent, service).
    PrincipalId,
    "pr"
);
define_id!(
    /// Identity of a repository within an instance.
    RepoId,
    "rp"
);
define_id!(
    /// Identity of an operation in a workspace's operation log. Also used as
    /// the idempotency key for write RPCs.
    OperationId,
    "op"
);

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn display_roundtrip() {
        let id = ChangeId::new();
        let s = id.to_string();
        assert!(s.starts_with("ch_"));
        assert_eq!(s.parse::<ChangeId>().unwrap(), id);
        assert_eq!(id.to_hex().parse::<ChangeId>().unwrap(), id);
    }

    #[test]
    fn derived_is_deterministic() {
        assert_eq!(
            ChangeId::derived("git", "abc"),
            ChangeId::derived("git", "abc")
        );
        assert_ne!(
            ChangeId::derived("git", "abc"),
            ChangeId::derived("git", "abd")
        );
    }
}
